WITH with_windows AS (SELECT *, ROW_NUMBER() OVER w_recent AS event_seq, SUM(duration_sec) OVER (PARTITION BY session_id ORDER BY duration_sec ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec, FIRST_VALUE(duration_sec) IGNORE NULLS OVER (ORDER BY duration_sec ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_duration_sec, NTILE(10) OVER w_recent AS duration_sec_bucket, AVG(duration_sec) OVER (PARTITION BY session_id ORDER BY duration_sec ASC, id ASC ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS duration_sec_avg_6_prior FROM web_events WINDOW w_recent AS (PARTITION BY page ORDER BY duration_sec ASC, id ASC)) SELECT page, ROUND(SUM(cumulative_duration_sec) / NULLIF(COUNT(CASE WHEN event_type = 'click' THEN 1 END), 0), 2) AS cumulative_duration_sec_per_click, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS duration_min, COUNT(*) AS cnt, MAX(event_time) AS last_seen, ROUND(SUM(duration_sec_bucket) / NULLIF(COUNT(CASE WHEN event_type = 'add_to_cart' THEN 1 END), 0), 2) AS duration_sec_bucket_per_add_to_cart FROM with_windows GROUP BY page;
